<script lang="ts">
  import type { NpcPlanStep, NpcProfileEntryKind, NpcSheet } from '$lib/game/npc-sheet';
  import type { Snippet } from 'svelte';
  import { DIFFICULTY_LEVELS, DISCLOSURE_LEVELS, fromGuidedNpcSheet, newGuidedEntity, newGuidedFact, newGuidedMilestone, newInitialPersonalityEntry, removeGuidedEntity, removeGuidedNpcReference, toGuidedNpcSheet, type GuidedMilestone, type GuidedNpcSheet } from '$lib/game/npc-sheet-editor';
  import { enhance } from '$app/forms'; import type { SubmitFunction } from '@sveltejs/kit'; import { onMount } from 'svelte';
  type RelatedNpc = { id:string; name:string };
  const kinds: readonly NpcProfileEntryKind[]=['value','boundary','preference','aversion','motive','fear','coping_pattern','voice_trait'];
  const required: readonly NpcProfileEntryKind[]=['value','boundary','preference','aversion','voice_trait'];
  let { sheet, revision, editable=true, conflict=false, message='', relatedNpcs=[], children }: {sheet:NpcSheet;revision:number;editable?:boolean;conflict?:boolean;message?:string;relatedNpcs?:RelatedNpc[];children?:Snippet}=$props();
  let form:HTMLFormElement; let hydrated=$state(false); let frozen=$state(false); let status=$state('Saved'); let worldOpen=$state(false); let storyOpen=$state(true); let entityError=$state(''); let timer:ReturnType<typeof setTimeout>|undefined;
  function initialEditor(){return toGuidedNpcSheet(sheet)}
  let editor=$state<GuidedNpcSheet>(initialEditor()); $effect(()=>{editor=toGuidedNpcSheet(sheet)}); let canonical=$derived(fromGuidedNpcSheet(editor));
  let entryKind=$state<NpcProfileEntryKind>('value');
  const missing=$derived(required.filter((kind)=>!editor.personality.initialEntries.some((entry)=>entry.kind===kind)));
  const palette=$derived(editor.appearance.palette.join('\n'));
  onMount(()=>{hydrated=true});
  function schedule(){if(!hydrated||!editable||frozen)return;status='Saving…';if(timer)clearTimeout(timer);timer=setTimeout(()=>form.requestSubmit(),700)}
  const autosave:SubmitFunction=()=>async({result,update})=>{const data=(result.type==='failure'||result.type==='success'?result.data:undefined) as {message?:string;conflict?:boolean}|undefined;if(result.type==='failure'){if(data?.conflict){frozen=true;status='Conflict — refresh before editing'}else status=data?.message??'Save failed';await update({reset:false,invalidateAll:false});return}status='Saved';await update({reset:false,invalidateAll:true})};
  const lines=(text:string)=>text.split('\n').map((x)=>x.trim()).filter(Boolean);
  function addDimension(){if(editor.personality.dimensions.length<8){const n=editor.personality.dimensions.length+1;editor.personality.dimensions.push({key:`dimension_${n}`,label:`Dimension ${n}`,negativeAnchor:'withdrawn',positiveAnchor:'engaged',initialValue:0,volatility:1,ordinaryChangeThreshold:25,definingRuptureThreshold:100})}}
  function addCollection(){const kind=kinds.find((x)=>!editor.personality.collections.some((c)=>c.kind===x));if(kind)editor.personality.collections.push({kind,maximumEntries:4})}
  function cap(kind:NpcProfileEntryKind){return editor.personality.collections.find((c)=>c.kind===kind)?.maximumEntries??0}
  function addEntry(){if(editor.personality.initialEntries.filter((e)=>e.kind===entryKind).length<cap(entryKind))editor.personality.initialEntries.push(newInitialPersonalityEntry(editor,entryKind))}
  function move<T>(items:T[],index:number,by:number){const target=index+by;if(target<0||target>=items.length)return;[items[index],items[target]]=[items[target],items[index]]}
  function removeEntity(id:string){const result=removeGuidedEntity(editor,id);entityError=result.ok?'':result.message}
  function toggle(values:string[],value:string,checked:boolean){return checked?[...new Set([...values,value])]:values.filter((entry)=>entry!==value)}
  function linkedName(id:string){return relatedNpcs.find((npc)=>npc.id===id)?.name??'A linked character'}
  function addNpc(id:string){if(id&&!editor.world.npcReferences.includes(id))editor.world.npcReferences.push(id)}
  function addRelationship(){const entity=editor.world.entities[0];const npcId=editor.world.npcReferences[0];if(!entity&&!npcId)return;editor.world.relationships.push({subject:entity?{kind:'entity',entityId:entity.id}:{kind:'npc',npcId:npcId!},description:'Describe this connection.',disclosure:'trusted'})}
  function setRelationshipSubject(index:number,value:string){const [kind,id]=value.split(':');editor.world.relationships[index].subject=kind==='npc'?{kind:'npc',npcId:id}:{kind:'entity',entityId:id}}
  function addPlanStep(milestone:GuidedMilestone){const current=milestone.startingPlan??[];if(current.length>=3)return;const approach=current.at(-1)?.approach??'scouting';milestone.startingPlan=(current.length?[...current.slice(0,-1),{action:'prepare',approach},{action:'attempt',approach}]:[{action:'attempt',approach}]) as NpcPlanStep[]}
  function removePlanStep(milestone:GuidedMilestone,index:number){const next=(milestone.startingPlan??[]).filter((_,itemIndex)=>itemIndex!==index);if(!next.length){milestone.startingPlan=null;return}next[next.length-1].action='attempt';milestone.startingPlan=next}
</script>

{#if message}<p class="community-notice" class:community-error={conflict} role={conflict?'alert':'status'}>{message}</p>{/if}
<form bind:this={form} method="POST" action="?/save" class="npc-editor" use:enhance={autosave} oninput={schedule}>
  <input type="hidden" name="revision" value={revision}/><input type="hidden" name="appearance" value={JSON.stringify(canonical.appearance)}/><input type="hidden" name="personality" value={JSON.stringify(canonical.personality)}/><input type="hidden" name="skills" value={JSON.stringify(canonical.skills)}/><input type="hidden" name="entities" value={JSON.stringify(canonical.lore.entities)}/><input type="hidden" name="facts" value={JSON.stringify(canonical.lore.facts)}/><input type="hidden" name="relationships" value={JSON.stringify(canonical.lore.relationships)}/><input type="hidden" name="npcReferences" value={JSON.stringify(canonical.lore.npcReferences)}/><input type="hidden" name="milestones" value={JSON.stringify(canonical.campaign.milestones)}/>
  <div class="npc-editor-toolbar"><span class="eyebrow">Draft revision {revision}</span><span aria-live="polite">{!editable?'Read-only':status}</span></div>
  <fieldset disabled={!hydrated||!editable||frozen}>
    <section class="editor-section"><div class="editor-section-heading"><span>01</span><div><h2>Identity</h2><p>Public introduction and voice rules.</p></div></div><div class="editor-fields two-column"><label>Name<input name="name" bind:value={editor.identity.name} required/></label><label>Title<input name="title" bind:value={editor.identity.title} required/></label></div><label>Short description<textarea name="shortDescription" bind:value={editor.identity.shortDescription} required></textarea></label><label>Voice and speech rules<textarea name="voice" bind:value={editor.identity.voice} required></textarea></label><label>Audience<select name="rating" bind:value={editor.rating}><option value="standard">Standard</option><option value="mature">Mature</option></select></label></section>
    <section class="editor-section"><div class="editor-section-heading"><span>02</span><div><h2>Appearance</h2><p>These fields create the portrait and scene brief.</p></div></div><div class="editor-fields two-column"><label>Physical appearance<textarea bind:value={editor.appearance.physicalAppearance} required></textarea></label><label>Recognizable silhouette<textarea bind:value={editor.appearance.silhouette} required></textarea></label><label>Attire<textarea bind:value={editor.appearance.attire} required></textarea></label><label>Notable features<textarea bind:value={editor.appearance.notableFeatures} required></textarea></label><label>Default mood<textarea bind:value={editor.appearance.mood} required></textarea></label><label>Palette keys<textarea value={palette} oninput={(e)=>editor.appearance.palette=lines((e.currentTarget as HTMLTextAreaElement).value).map((x)=>x.toLowerCase().replaceAll(' ','-')).slice(0,5)} required></textarea><small>One lowercase key per line, up to five.</small></label></div></section>
    {@render children?.()}
    <section class="editor-section"><div class="editor-section-heading"><span>03</span><div><h2>Evolution</h2><p>Define what changes in play and the authored profile that stays true.</p></div></div><div class="guided-heading"><h3>Personality dimensions</h3><button type="button" class="secondary-action" disabled={editor.personality.dimensions.length>=8} onclick={addDimension}>Add dimension</button></div>{#each editor.personality.dimensions as dimension,index (dimension.key)}<article class="repeater-card"><header><strong>Dimension {index+1}</strong><button type="button" class="quiet-danger" disabled={editor.personality.dimensions.length<=1} onclick={()=>editor.personality.dimensions.splice(index,1)}>Remove</button></header><div class="editor-fields two-column"><label>Stable key<input bind:value={dimension.key} required/></label><label>Reader label<input bind:value={dimension.label} required/></label><label>Negative anchor<input bind:value={dimension.negativeAnchor} required/></label><label>Positive anchor<input bind:value={dimension.positiveAnchor} required/></label><label>Starting value<input type="number" min="-100" max="100" bind:value={dimension.initialValue}/></label><label>Volatility<input type="number" min=".25" max="2" step=".05" bind:value={dimension.volatility}/></label><label>Ordinary threshold<input type="number" min="5" max="200" bind:value={dimension.ordinaryChangeThreshold}/></label><label>Defining threshold<input type="number" min="5" max="200" bind:value={dimension.definingRuptureThreshold}/></label></div></article>{/each}
      <div class="guided-heading"><h3>Collection caps</h3><button type="button" class="secondary-action" disabled={editor.personality.collections.length>=kinds.length} onclick={addCollection}>Add collection</button></div><div class="collection-grid">{#each editor.personality.collections as collection,index (collection.kind)}<label>{collection.kind.replaceAll('_',' ')} cap<input type="number" min="0" max="10" bind:value={collection.maximumEntries}/><button type="button" class="quiet-danger" onclick={()=>editor.personality.collections.splice(index,1)}>Remove</button></label>{/each}</div>
      <div class="guided-heading"><div><h3>Initial profile entries</h3>{#if missing.length}<p class="inline-error" role="status">Required before submission: {missing.join(', ')}.</p>{/if}</div><div><select aria-label="Entry kind" bind:value={entryKind}>{#each editor.personality.collections as collection}<option value={collection.kind}>{collection.kind.replaceAll('_',' ')}</option>{/each}</select><button type="button" class="secondary-action" onclick={addEntry}>Add entry</button></div></div>{#each editor.personality.initialEntries as entry,index (entry.id)}<article class="repeater-card"><header><strong>{entry.kind.replaceAll('_',' ')}</strong><button type="button" class="quiet-danger" onclick={()=>editor.personality.initialEntries.splice(index,1)}>Remove</button></header><div class="editor-fields two-column"><label>Stable ID<input bind:value={entry.id} required/></label><label>Kind<select bind:value={entry.kind}>{#each editor.personality.collections as collection}<option value={collection.kind}>{collection.kind.replaceAll('_',' ')}</option>{/each}</select></label></div><label>Authored statement<textarea bind:value={entry.text} required></textarea></label><label><input type="checkbox" bind:checked={entry.core}/> Core: this stays central to the NPC.</label></article>{/each}</section>
    <section class="editor-section guided-section">
      <button class="section-toggle" type="button" onclick={()=>worldOpen=!worldOpen} aria-expanded={worldOpen}><span class="section-number">04</span><span><strong>Their world and what they reveal</strong><small>Places, people, connections, and knowledge that this character can support in play.</small></span><span class="toggle-mark">{worldOpen?'−':'+'}</span></button>
      {#if worldOpen}<div class="guided-content">
        <div class="guided-heading"><div><h3>Story details</h3><p>Name the people, places, objects, and events that make their world specific.</p></div><button type="button" class="secondary-action" onclick={()=>editor.world.entities.push(newGuidedEntity(editor))}>Add detail</button></div>
        {#if entityError}<p class="inline-error" role="alert">{entityError}</p>{/if}
        {#each editor.world.entities as entity,index (entity.id)}<article class="repeater-card"><header><strong>Story detail {index+1}</strong><button class="quiet-danger" type="button" onclick={()=>removeEntity(entity.id)}>Remove</button></header><div class="editor-fields two-column"><label>Name<input bind:value={entity.name}/></label><label>Kind<select bind:value={entity.namespace}><option value="tavern">Tavern life</option><option value="place">Place</option><option value="group">Group</option><option value="object">Object</option><option value="event">Event</option></select></label></div><label>Description<textarea bind:value={entity.description}></textarea></label></article>{:else}<p class="empty-guided">No story details yet. Add only details this character can actually know.</p>{/each}
        <div class="guided-heading"><div><h3>Other characters they may mention</h3><p>These links remain internal; player-facing dialogue uses the authored relationship and facts below.</p></div></div><div class="npc-picker"><select aria-label="Choose another character" onchange={(event)=>{addNpc((event.currentTarget as HTMLSelectElement).value);(event.currentTarget as HTMLSelectElement).value=''}}><option value="">Choose a character…</option>{#each relatedNpcs as npc}<option value={npc.id} disabled={editor.world.npcReferences.includes(npc.id)}>{npc.name}</option>{/each}</select></div><div class="chip-list">{#each editor.world.npcReferences as npcId (npcId)}<span class="linked-chip">{linkedName(npcId)} <button type="button" aria-label={`Remove ${linkedName(npcId)}`} onclick={()=>removeGuidedNpcReference(editor,npcId)}>×</button></span>{:else}<p class="empty-guided">No other characters are linked yet.</p>{/each}</div>
        <div class="guided-heading"><div><h3>Connections</h3><p>Describe who or what matters and when it can be discussed.</p></div><button type="button" class="secondary-action" disabled={!editor.world.entities.length&&!editor.world.npcReferences.length} onclick={addRelationship}>Add connection</button></div>
        {#each editor.world.relationships as relationship,index}<article class="repeater-card"><header><strong>Connection {index+1}</strong><button class="quiet-danger" type="button" onclick={()=>editor.world.relationships.splice(index,1)}>Remove</button></header><div class="editor-fields two-column"><label>Connected to<select value={relationship.subject.kind==='entity'?`entity:${relationship.subject.entityId}`:`npc:${relationship.subject.npcId}`} onchange={(event)=>setRelationshipSubject(index,(event.currentTarget as HTMLSelectElement).value)}><option value="">Choose…</option>{#each editor.world.entities as entity}<option value={`entity:${entity.id}`}>{entity.name||'Untitled detail'}</option>{/each}{#each editor.world.npcReferences as npcId}<option value={`npc:${npcId}`}>{linkedName(npcId)}</option>{/each}</select></label><label>Disclosure<select bind:value={relationship.disclosure}>{#each DISCLOSURE_LEVELS as level}<option value={level.value}>{level.label}</option>{/each}</select></label></div><label>How are they connected?<textarea bind:value={relationship.description}></textarea></label></article>{:else}<p class="empty-guided">No connections yet.</p>{/each}
        <div class="guided-heading"><div><h3>Things they know</h3><p>Facts are separate from world canon: a conversation cannot make a player claim true.</p></div><button type="button" class="secondary-action" onclick={()=>editor.world.facts.push(newGuidedFact(editor))}>Add fact</button></div>
        {#each editor.world.facts as fact,index (fact.id)}<article class="repeater-card"><header><strong>Thing they know {index+1}</strong><button class="quiet-danger" type="button" onclick={()=>editor.world.facts.splice(index,1)}>Remove</button></header><div class="editor-fields two-column"><label>Category<select bind:value={fact.category}><option value="history">Past experience</option><option value="relationship">Relationship</option><option value="goal">Current goal</option><option value="secret">Private secret</option></select></label><label>Disclosure<select bind:value={fact.disclosure}>{#each DISCLOSURE_LEVELS as level}<option value={level.value}>{level.label}</option>{/each}</select></label></div><label>What do they know?<textarea bind:value={fact.text}></textarea></label><fieldset class="reference-picker"><legend>Related story details</legend>{#each editor.world.entities as entity}<label><input type="checkbox" checked={fact.entityRefs.includes(entity.id)} onchange={(event)=>fact.entityRefs=toggle(fact.entityRefs,entity.id,(event.currentTarget as HTMLInputElement).checked)}/> {entity.name||'Untitled detail'}</label>{/each}</fieldset><fieldset class="reference-picker"><legend>Other characters</legend>{#each editor.world.npcReferences as npcId}<label><input type="checkbox" checked={fact.npcRefs.includes(npcId)} onchange={(event)=>fact.npcRefs=toggle(fact.npcRefs,npcId,(event.currentTarget as HTMLInputElement).checked)}/> {linkedName(npcId)}</label>{/each}</fieldset></article>{:else}<p class="empty-guided">No facts yet. Add only knowledge this character can support in play.</p>{/each}
      </div>{/if}
    </section>
    <section class="editor-section"><div class="editor-section-heading"><span>05</span><div><h2>Skills</h2><p>Scores total ten, include one 4, and one score of 1 or lower.</p></div></div><div class="skill-grid">{#each Object.entries(editor.skills) as [skill]}<label>{skill}<input type="number" min="0" max="4" step="1" bind:value={editor.skills[skill as keyof typeof editor.skills]}/></label>{/each}</div></section>
    <section class="editor-section guided-section"><button class="section-toggle" type="button" onclick={()=>storyOpen=!storyOpen} aria-expanded={storyOpen}><span class="section-number">06</span><span><strong>Their story arc</strong><small>The hopes, chapters, and lasting stakes that guide choices.</small></span><span class="toggle-mark">{storyOpen?'−':'+'}</span></button>
      {#if storyOpen}<div class="guided-content"><label class="long-goal">Their long-term hope or goal<textarea name="durableGoal" bind:value={editor.story.durableGoal} required></textarea></label><div class="guided-heading"><div><h3>Chapters</h3><p>The opening chapter carries an authored starting plan; later chapters respond to the world as it changes.</p></div><button type="button" class="secondary-action" onclick={()=>editor.story.milestones.push(newGuidedMilestone(editor))}>Add chapter</button></div>
      {#each editor.story.milestones as milestone,index (milestone.id)}<article class="milestone-card"><header><div><span class="chapter-label">Chapter {index+1}</span><strong>{milestone.title||'Untitled chapter'}</strong></div><div class="order-actions"><button type="button" disabled={index===0} onclick={()=>move(editor.story.milestones,index,-1)}>Move earlier</button><button type="button" disabled={index===editor.story.milestones.length-1} onclick={()=>move(editor.story.milestones,index,1)}>Move later</button><button type="button" class="quiet-danger" disabled={editor.story.milestones.length<=2} onclick={()=>editor.story.milestones.splice(index,1)}>Remove</button></div></header><div class="editor-fields two-column"><label>Chapter title<input bind:value={milestone.title}/></label><label>Difficulty<select bind:value={milestone.difficulty}>{#each DIFFICULTY_LEVELS as level}<option value={level.value}>{level.label}</option>{/each}</select></label></div><label>What does success look like?<textarea bind:value={milestone.outcome}></textarea></label><label>Why does this matter?<textarea bind:value={milestone.motivation}></textarea></label><label>Boundaries they will not cross<textarea value={milestone.constraints.join('\n')} oninput={(event)=>milestone.constraints=lines((event.currentTarget as HTMLTextAreaElement).value)}></textarea></label><label>Situations this chapter may involve<textarea value={milestone.allowedTargets.join('\n')} oninput={(event)=>milestone.allowedTargets=lines((event.currentTarget as HTMLTextAreaElement).value)}></textarea></label><div class="editor-fields two-column"><label>News after success<textarea bind:value={milestone.successNews}></textarea></label><label>News after a setback<textarea bind:value={milestone.nonSuccessNews}></textarea></label></div>
      {#if index===0}<fieldset class="plan-builder"><legend>Opening plan</legend><p>Choose up to three ordered moves. The final move resolves as an attempt or abandonment.</p>{#each milestone.startingPlan??[] as step,stepIndex}<div class="plan-step"><span>{stepIndex+1}</span><select bind:value={step.action}>{#if stepIndex<(milestone.startingPlan?.length??0)-1}<option value="prepare">Prepare</option><option value="wait">Wait</option>{:else}<option value="attempt">Attempt</option><option value="abandon">Abandon</option>{/if}</select><select bind:value={step.approach}><option value="scouting">Scout</option><option value="combat">Combat</option><option value="diplomacy">Diplomacy</option><option value="trade">Trade</option></select><button type="button" class="quiet-danger" onclick={()=>removePlanStep(milestone,stepIndex)}>Remove</button></div>{/each}<button type="button" class="secondary-action" disabled={(milestone.startingPlan?.length??0)>=3} onclick={()=>addPlanStep(milestone)}>Add a step</button></fieldset>{:else}<p class="later-plan">This chapter’s plan will be determined after earlier events resolve.</p>{/if}
      <details class="advanced-loss"><summary>Advanced setback and permanent loss</summary><label><input type="checkbox" checked={milestone.permanentLoss!==null} onchange={(event)=>milestone.permanentLoss=(event.currentTarget as HTMLInputElement).checked?{kind:'departed',warning:'A visible warning must appear before this loss can happen.',outcome:'Describe the permanent consequence.'}:null}/> This chapter can permanently remove the character</label>{#if milestone.permanentLoss}<div class="editor-fields two-column"><label>Outcome<select bind:value={milestone.permanentLoss.kind}><option value="departed">They depart</option><option value="dead">They die</option></select></label><label>Visible warning<textarea bind:value={milestone.permanentLoss.warning}></textarea></label><label>Permanent outcome<textarea bind:value={milestone.permanentLoss.outcome}></textarea></label></div>{/if}</details></article>{/each}</div>{/if}
    </section>
    <div class="npc-editor-footer"><p>Saving keeps the revision editable. Submission freezes a reviewed snapshot.</p><button class="primary-action" type="submit">Save draft revision {revision}</button></div>
  </fieldset>
</form>

<style>
 .guided-section{padding:0;overflow:hidden}.section-toggle{width:100%;display:flex;gap:1rem;align-items:center;text-align:left;padding:1.25rem;border:0;background:linear-gradient(120deg,rgba(75,57,21,.35),transparent);color:inherit;cursor:pointer}.section-toggle strong,.section-toggle small{display:block}.section-toggle strong{font:700 1.15rem Georgia,serif;color:#f2d180}.section-toggle small{margin-top:.2rem;color:#c9b891}.section-number{color:#e5ba58;font:700 1.2rem Georgia,serif}.toggle-mark{margin-left:auto;font-size:1.55rem;color:#e5ba58}.guided-content{padding:0 1.25rem 1.3rem;border-top:1px solid rgba(212,164,62,.22)}.guided-heading{display:flex;justify-content:space-between;align-items:flex-end;gap:1rem;margin:1rem 0}.guided-heading h3{margin:0;color:#efd180}.guided-heading p,.long-goal{color:#c7b995}.repeater-card,.milestone-card{margin:.8rem 0;padding:1rem;border:1px solid rgba(212,164,62,.28);background:rgba(10,8,4,.43);border-radius:5px}.repeater-card header,.milestone-card header{display:flex;justify-content:space-between;gap:1rem;color:#efd180}.secondary-action,.order-actions button{border:1px solid #9c752a;color:#f0d584;background:rgba(50,37,10,.68);padding:.45rem .7rem;cursor:pointer}.quiet-danger{border:0;background:transparent;color:#df9d83;cursor:pointer}.collection-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(14rem,1fr));gap:.6rem}.collection-grid label{display:grid;grid-template-columns:1fr 4rem auto;gap:.4rem;align-items:center;text-transform:capitalize}.inline-error{color:#ffb3a1;background:rgba(112,24,14,.25);padding:.6rem}.empty-guided,.later-plan{padding:.8rem;border-left:3px solid #8d7338;color:#bdae8d;background:rgba(54,43,21,.2)}.chip-list{display:flex;gap:.5rem;flex-wrap:wrap;margin:.65rem 0}.linked-chip{display:inline-flex;gap:.4rem;align-items:center;padding:.35rem .55rem;background:#233224;color:#d7e7ba;border:1px solid #4d7444;border-radius:999px}.linked-chip button{border:0;color:inherit;background:transparent;font-size:1.1rem;cursor:pointer}.npc-picker select{width:100%;max-width:26rem}.reference-picker,.plan-builder{margin:.8rem 0;padding:.8rem;border:1px solid rgba(212,164,62,.25)}.reference-picker label{display:inline-flex;margin:.2rem .75rem .2rem 0;color:#d2c3a1}.chapter-label{display:block;color:#ad8d45;font-size:.76rem;text-transform:uppercase;letter-spacing:.08em}.order-actions{display:flex;flex-wrap:wrap;gap:.35rem}.order-actions button:disabled{opacity:.35;cursor:not-allowed}.plan-step{display:grid;grid-template-columns:2rem 1fr 1fr auto;gap:.5rem;align-items:center;margin:.5rem 0}.plan-step>span{color:#e5ba58}.advanced-loss{margin-top:1rem;padding-top:.8rem;border-top:1px solid rgba(212,164,62,.2);color:#c8b894}.advanced-loss summary{cursor:pointer;color:#d6b564}.long-goal{display:block;margin-top:1rem}@media(max-width:700px){.guided-heading,.repeater-card header,.milestone-card header{align-items:stretch;flex-direction:column}.collection-grid label{grid-template-columns:1fr 4rem auto}.plan-step{grid-template-columns:1.6rem 1fr}.plan-step button{grid-column:2;justify-self:start}}
</style>
